SELECT soh.salesorderid AS id_external FROM ADVENTUREWORKS.SALESORDERHEADER soh WHERE soh.comment LIKE '%Cleanup%' ORDER BY soh.orderdate DESC LIMIT 10;
SELECT soh.salesorderid AS id_external FROM ADVENTUREWORKS.SALESORDERHEADER soh WHERE soh.orderdate >= '2001-01-01 00:00:00' AND soh.orderdate < '2026-01-31 23:59:59' ORDER BY soh.orderdate DESC LIMIT 10;
SELECT soh.salesorderid AS id_external FROM ADVENTUREWORKS.SALESORDERHEADER soh WHERE soh.STATUS = '5' ORDER BY soh.orderdate DESC LIMIT 10;
SELECT soh.salesorderid AS id_external FROM ADVENTUREWORKS.SALESORDERHEADER soh WHERE soh.orderdate >= '2001-01-01 00:00:00' AND soh.orderdate < '2026-01-31 23:59:59' AND soh.STATUS = 5 AND soh.comment LIKE CONCAT('%', '%good%', '%') ORDER BY soh.orderdate DESC LIMIT 10;
SELECT COUNT(*) AS event_cnt FROM ADVENTUREWORKS.SALESORDERHEADER soh WHERE soh.orderdate >= '2001-01-01 00:00:00' AND soh.orderdate < '2026-01-31 23:59:59';
SELECT COUNT(DISTINCT soh.territoryid) AS distinct_entity_cnt FROM ADVENTUREWORKS.SALESORDERHEADER soh WHERE soh.orderdate >= '2001-01-01 00:00:00' AND soh.orderdate < '2026-01-31 23:59:59';
SELECT SUM(soh.totaldue) AS total_amount FROM ADVENTUREWORKS.SALESORDERHEADER soh WHERE soh.orderdate >= '2001-01-01 00:00:00' AND soh.orderdate < '2026-01-31 23:59:59';
SELECT AVG(soh.totaldue) AS avg_amount FROM ADVENTUREWORKS.SALESORDERHEADER soh WHERE soh.orderdate >= '2001-01-01 00:00:00' AND soh.orderdate < '2026-01-31 23:59:59';
SELECT p.productline AS category_topic, COUNT(*) AS event_cnt FROM ADVENTUREWORKS.SALESORDERHEADER soh JOIN ADVENTUREWORKS.SALESORDERDETAIL sod ON sod.salesorderid = soh.salesorderid JOIN ADVENTUREWORKS.PRODUCT p ON p.productid = sod.productid WHERE soh.orderdate >= '2001-01-01' AND soh.orderdate < '2024-01-31' GROUP BY p.productline ORDER BY event_cnt DESC LIMIT 10;
SELECT p.productline AS category_topic, COUNT(DISTINCT sod.productid) AS distinct_entity_cnt FROM ADVENTUREWORKS.SALESORDERHEADER soh JOIN ADVENTUREWORKS.SALESORDERDETAIL sod ON sod.salesorderid = soh.salesorderid JOIN ADVENTUREWORKS.PRODUCT p ON p.productid = sod.productid WHERE soh.orderdate >= '2001-01-01' AND soh.orderdate < '2024-01-31' GROUP BY p.productline ORDER BY distinct_entity_cnt DESC LIMIT 10;
SELECT st.name AS name_entity, COUNT(*) AS event_cnt FROM ADVENTUREWORKS.SALESORDERHEADER soh JOIN ADVENTUREWORKS.SALESTERRITORY st ON st.territoryid = soh.territoryid WHERE soh.orderdate >= '2001-01-01 00:00:00' AND soh.orderdate < '2026-01-31 23:59:59' GROUP BY st.name ORDER BY event_cnt DESC LIMIT 10;
SELECT st.name AS name_entity, SUM(soh.totaldue) AS total_amount FROM ADVENTUREWORKS.SALESORDERHEADER soh JOIN ADVENTUREWORKS.SALESTERRITORY st ON st.territoryid = soh.territoryid WHERE soh.orderdate >= '2001-01-01 00:00:00' AND soh.orderdate < '2026-01-31 23:59:59' GROUP BY st.name ORDER BY total_amount DESC LIMIT 10;
SELECT st.countryregioncode AS location, COUNT(*) AS event_cnt FROM ADVENTUREWORKS.SALESORDERHEADER soh JOIN ADVENTUREWORKS.SALESTERRITORY st ON st.territoryid = soh.territoryid WHERE soh.orderdate >= '2001-01-01 00:00:00' AND soh.orderdate < '2026-01-31 23:59:59' GROUP BY st.countryregioncode ORDER BY event_cnt DESC LIMIT 10;
SELECT soh.salespersonid AS rel_person, COUNT(*) AS event_cnt FROM ADVENTUREWORKS.SALESORDERHEADER soh WHERE soh.orderdate >= '2001-01-01 00:00:00' AND soh.orderdate < '2026-01-31 23:59:59' GROUP BY soh.salespersonid ORDER BY event_cnt DESC LIMIT 10;
SELECT DATE(soh.orderdate) AS day, COUNT(*) AS event_cnt FROM ADVENTUREWORKS.SALESORDERHEADER soh WHERE soh.orderdate >= '2001-01-01 00:00:00' AND soh.orderdate < '2026-01-31 23:59:59' GROUP BY day ORDER BY day;
SELECT DATE_FORMAT(soh.orderdate, '%Y-%m-01') AS month, SUM(soh.totaldue) AS total_amount FROM ADVENTUREWORKS.SALESORDERHEADER soh WHERE soh.orderdate >= '2001-01-01 00:00:00' AND soh.orderdate < '2026-01-31 23:59:59' GROUP BY month ORDER BY month;
SELECT DATE( soh.orderdate) AS day, p.productline AS category_topic, COUNT(*) AS event_cnt FROM ADVENTUREWORKS.SALESORDERHEADER soh JOIN ADVENTUREWORKS.SALESORDERDETAIL sod ON sod.salesorderid = soh.salesorderid JOIN ADVENTUREWORKS.PRODUCT p ON p.productid = sod.productid WHERE soh.orderdate >= '2001-01-01 00:00:00' AND soh.orderdate < '2026-01-31 23:59:59' GROUP BY day, p.productline ORDER BY day, event_cnt DESC;
SELECT st.name AS name_entity, COUNT(*) AS event_cnt FROM ADVENTUREWORKS.SALESORDERHEADER soh JOIN ADVENTUREWORKS.SALESTERRITORY st ON st.territoryid = soh.territoryid WHERE soh.orderdate >= '2001-01-01 00:00:00' AND soh.orderdate < '2026-01-31 23:59:59' GROUP BY st.name HAVING COUNT(*) >= 10 ORDER BY event_cnt DESC;
SELECT st.name AS name_entity, AVG(soh.totaldue) AS avg_amount FROM ADVENTUREWORKS.SALESORDERHEADER soh JOIN ADVENTUREWORKS.SALESTERRITORY st ON st.territoryid = soh.territoryid WHERE soh.orderdate >= '2001-01-01 00:00:00' AND soh.orderdate < '2026-01-31 23:59:59' AND soh.totaldue IS NOT NULL GROUP BY st.name ORDER BY avg_amount DESC LIMIT 10;
SELECT DISTINCT p.NAME AS name_entity FROM ADVENTUREWORKS.PRODUCTREVIEW pr JOIN ADVENTUREWORKS.PRODUCT p ON p.productid = pr.productid WHERE pr.reviewdate >= '2001-01-01 00:00:00' AND pr.reviewdate < '2026-01-31 23:59:59' AND pr.comments LIKE '%good%' ORDER BY p.NAME LIMIT 10;
WITH topic_cnt AS ( SELECT p.productline AS topic, COUNT(*) AS cnt FROM ADVENTUREWORKS.SALESORDERHEADER soh JOIN ADVENTUREWORKS.SALESORDERDETAIL sod ON sod.salesorderid = soh.salesorderid JOIN ADVENTUREWORKS.PRODUCT p ON p.productid = sod.productid WHERE soh.orderdate >= '2001-01-01 00:00:00' AND soh.orderdate < '2026-01-31 23:59:59' GROUP BY p.productline ), avg_cnt AS ( SELECT AVG(cnt) AS avg_cnt FROM topic_cnt ) SELECT topic, cnt FROM topic_cnt WHERE cnt > (SELECT avg_cnt FROM avg_cnt) ORDER BY cnt DESC LIMIT 10;
SELECT soh.salespersonid AS rel_person, p.productline AS category_topic, COUNT(*) AS event_cnt FROM ADVENTUREWORKS.SALESORDERHEADER soh JOIN ADVENTUREWORKS.SALESORDERDETAIL sod ON sod.salesorderid = soh.salesorderid JOIN ADVENTUREWORKS.PRODUCT p ON p.productid = sod.productid WHERE soh.orderdate >= '2001-01-01 00:00:00' AND soh.orderdate < '2026-01-31 23:59:59' GROUP BY soh.salespersonid, p.productline ORDER BY event_cnt DESC LIMIT 10;
SELECT f.flight_no AS id_external FROM AIRLINES.FLIGHTS f WHERE f.scheduled_departure >= '2001-01-01 00:00:00' AND f.scheduled_departure < '2026-01-31 23:59:59' ORDER BY f.scheduled_departure DESC LIMIT 10;
SELECT f.flight_no AS id_external FROM AIRLINES.FLIGHTS f WHERE f.status = 'Scheduled' ORDER BY f.scheduled_departure DESC LIMIT 10;
SELECT COUNT(*) AS event_cnt FROM AIRLINES.FLIGHTS f WHERE f.scheduled_departure >= '2001-01-01 00:00:00' AND f.scheduled_departure < '2026-01-31 23:59:59';
SELECT COUNT(DISTINCT tf.flight_id) AS distinct_entity_cnt FROM AIRLINES.TICKET_FLIGHTS tf JOIN AIRLINES.FLIGHTS f ON f.flight_id = tf.flight_id WHERE f.scheduled_departure >= '2001-01-01 00:00:00' AND f.scheduled_departure < '2026-01-31 23:59:59';
SELECT SUM(b.total_amount) AS total_amount FROM AIRLINES.BOOKINGS b WHERE b.book_date >= '2001-01-01 00:00:00' AND b.book_date < '2026-01-31 23:59:59';
SELECT AVG(b.total_amount) AS avg_amount FROM AIRLINES.BOOKINGS b WHERE b.book_date >= '2001-01-01 00:00:00' AND b.book_date < '2026-01-31 23:59:59';
SELECT tf.fare_conditions AS category_topic, COUNT(*) AS event_cnt FROM AIRLINES.TICKET_FLIGHTS tf JOIN AIRLINES.FLIGHTS f ON f.flight_id = tf.flight_id WHERE f.scheduled_departure >= '2001-01-01 00:00:00' AND f.scheduled_departure < '2026-01-31 23:59:59' GROUP BY tf.fare_conditions ORDER BY event_cnt DESC LIMIT 10;
SELECT tf.fare_conditions AS category_topic, COUNT(DISTINCT tf.flight_id) AS distinct_entity_cnt FROM AIRLINES.TICKET_FLIGHTS tf JOIN AIRLINES.FLIGHTS f ON f.flight_id = tf.flight_id WHERE f.scheduled_departure >= '2001-01-01 00:00:00' AND f.scheduled_departure < '2026-01-31 23:59:59' GROUP BY tf.fare_conditions ORDER BY distinct_entity_cnt DESC LIMIT 10;
SELECT a.model AS name_entity, COUNT(*) AS event_cnt FROM AIRLINES.FLIGHTS f JOIN AIRLINES.AIRCRAFTS_DATA a ON a.aircraft_code = f.aircraft_code WHERE f.scheduled_departure >= '2001-01-01 00:00:00' AND f.scheduled_departure < '2026-01-31 23:59:59' GROUP BY a.model ORDER BY event_cnt DESC LIMIT 10;
SELECT a.model AS name_entity, SUM(tf.amount) AS total_amount FROM AIRLINES.FLIGHTS f JOIN AIRLINES.TICKET_FLIGHTS tf ON tf.flight_id = f.flight_id JOIN AIRLINES.AIRCRAFTS_DATA a ON a.aircraft_code = f.aircraft_code WHERE f.scheduled_departure >= '2001-01-01 00:00:00' AND f.scheduled_departure < '2026-01-31 23:59:59' GROUP BY a.model ORDER BY total_amount DESC LIMIT 10;
SELECT t.passenger_id AS rel_person, COUNT(*) AS event_cnt FROM AIRLINES.TICKETS t JOIN AIRLINES.BOOKINGS b ON b.book_ref = t.book_ref WHERE b.book_date >= '2001-01-01 00:00:00' AND b.book_date < '2026-01-31 23:59:59' GROUP BY t.passenger_id ORDER BY event_cnt DESC LIMIT 10;
SELECT DATE(f.scheduled_departure) AS day, COUNT(*) AS event_cnt FROM AIRLINES.FLIGHTS f WHERE f.scheduled_departure >= '2001-01-01 00:00:00' AND f.scheduled_departure < '2026-01-31 23:59:59' GROUP BY day ORDER BY day;
SELECT DATE_FORMAT(b.book_date, '%Y-%m-01') AS month, SUM(b.total_amount) AS total_amount FROM AIRLINES.BOOKINGS b WHERE b.book_date >= '2001-01-01 00:00:00' AND b.book_date < '2026-01-31 23:59:59' GROUP BY month ORDER BY month;
SELECT DATE( f.scheduled_departure) AS day, tf.fare_conditions AS category_topic, COUNT(*) AS event_cnt FROM AIRLINES.TICKET_FLIGHTS tf JOIN AIRLINES.FLIGHTS f ON f.flight_id = tf.flight_id WHERE f.scheduled_departure >= '2001-01-01 00:00:00' AND f.scheduled_departure < '2026-01-31 23:59:59' GROUP BY day, tf.fare_conditions ORDER BY day, event_cnt DESC;
SELECT a.model AS name_entity, COUNT(*) AS event_cnt FROM AIRLINES.FLIGHTS f JOIN AIRLINES.AIRCRAFTS_DATA a ON a.aircraft_code = f.aircraft_code WHERE f.scheduled_departure >= '2001-01-01 00:00:00' AND f.scheduled_departure < '2026-01-31 23:59:59' GROUP BY a.model HAVING COUNT(*) >= 10 ORDER BY event_cnt DESC;
SELECT a.model AS name_entity, AVG(tf.amount) AS avg_amount FROM AIRLINES.FLIGHTS f JOIN AIRLINES.TICKET_FLIGHTS tf ON tf.flight_id = f.flight_id JOIN AIRLINES.AIRCRAFTS_DATA a ON a.aircraft_code = f.aircraft_code WHERE f.scheduled_departure >= '2001-01-01 00:00:00' AND f.scheduled_departure < '2026-01-31 23:59:59' AND tf.amount IS NOT NULL GROUP BY a.model ORDER BY avg_amount DESC LIMIT 10;
WITH topic_cnt AS ( SELECT tf.fare_conditions AS topic, COUNT(*) AS cnt FROM AIRLINES.TICKET_FLIGHTS tf JOIN AIRLINES.FLIGHTS f ON f.flight_id = tf.flight_id WHERE f.scheduled_departure >= '2017-06-01 00:00:00' AND f.scheduled_departure < '2017-07-31 23:59:59' GROUP BY tf.fare_conditions ), avg_cnt AS ( SELECT AVG(cnt) AS avg_cnt FROM topic_cnt ) SELECT topic, cnt FROM topic_cnt WHERE cnt >= (SELECT avg_cnt FROM avg_cnt) ORDER BY cnt DESC LIMIT 10;
SELECT t.passenger_id AS rel_person, tf.fare_conditions AS category_topic, COUNT(*) AS event_cnt FROM AIRLINES.TICKETS t JOIN AIRLINES.TICKET_FLIGHTS tf ON tf.ticket_no = t.ticket_no JOIN AIRLINES.BOOKINGS b ON b.book_ref = t.book_ref WHERE b.book_date >= '2017-07-01 00:00:00' AND b.book_date < '2017-12-31 23:59:59' GROUP BY t.passenger_id, tf.fare_conditions ORDER BY event_cnt DESC LIMIT 10;
SELECT tf.fare_conditions AS category_topic, SUM(tf.amount) AS total_amount FROM AIRLINES.TICKET_FLIGHTS tf JOIN AIRLINES.FLIGHTS f ON f.flight_id = tf.flight_id WHERE f.scheduled_departure >= '2001-01-01 00:00:00' AND f.scheduled_departure < '2026-01-31 23:59:59' GROUP BY tf.fare_conditions ORDER BY total_amount DESC LIMIT 10;
SELECT tf.fare_conditions AS category_topic, SUM(tf.amount) AS total_amount FROM AIRLINES.TICKET_FLIGHTS tf JOIN AIRLINES.FLIGHTS f ON f.flight_id = tf.flight_id WHERE f.scheduled_departure >= '2001-01-01 00:00:00' AND f.scheduled_departure < '2026-01-31 23:59:59' GROUP BY tf.fare_conditions HAVING SUM(tf.amount) >= 1000 ORDER BY total_amount DESC;
SELECT tf.fare_conditions AS category_topic, CAST(SUM(CASE WHEN f.status = 'Business' THEN 1 ELSE 0 END) AS DOUBLE) / COUNT(*) AS ratio_in_status FROM AIRLINES.TICKET_FLIGHTS tf JOIN AIRLINES.FLIGHTS f ON f.flight_id = tf.flight_id WHERE f.scheduled_departure >= '2001-01-01 00:00:00' AND f.scheduled_departure < '2026-01-31 23:59:59' GROUP BY tf.fare_conditions ORDER BY ratio_in_status DESC LIMIT 10;
WITH agg AS ( SELECT tf.fare_conditions AS topic, a.model AS entity, SUM(tf.amount) AS total_amount FROM AIRLINES.FLIGHTS f JOIN AIRLINES.TICKET_FLIGHTS tf ON tf.flight_id = f.flight_id JOIN AIRLINES.AIRCRAFTS_DATA a ON a.aircraft_code = f.aircraft_code WHERE f.scheduled_departure >= '2001-01-01 00:00:00' AND f.scheduled_departure < '2026-01-31 23:59:59' GROUP BY tf.fare_conditions, a.model ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY total_amount DESC) AS rn FROM agg ) SELECT topic, entity, total_amount FROM ranked WHERE rn = 1 ORDER BY total_amount DESC LIMIT 10;
SELECT COUNT(*) AS row_cnt FROM BOWLINGLEAGUE.TOURNEY_MATCHES_ARCHIVE tma;
SELECT COUNT(DISTINCT tma.MatchID) AS distinct_external_cnt FROM BOWLINGLEAGUE.TOURNEY_MATCHES_ARCHIVE tma;
SELECT COUNT(DISTINCT bs.MatchID) AS distinct_entity_cnt FROM BOWLINGLEAGUE.BOWLER_SCORES bs;
SELECT tma.TourneyID AS rel_entity, COUNT(*) AS event_cnt FROM BOWLINGLEAGUE.TOURNEY_MATCHES_ARCHIVE tma GROUP BY tma.TourneyID ORDER BY event_cnt DESC LIMIT 10;
SELECT ss.name AS name_entity, COUNT(*) AS event_cnt FROM BOWLINGLEAGUE.SQLITE_SEQUENCE ss GROUP BY ss.name ORDER BY event_cnt DESC LIMIT 10;
SELECT distinct ss.seq AS id_external FROM BOWLINGLEAGUE.SQLITE_SEQUENCE ss WHERE ss.name LIKE '%Bowlers%' ORDER BY ss.seq LIMIT 10;
SELECT b.TeamID AS rel_entity, SUM(b.BowlerGamesBowled) AS total_quantity FROM BOWLINGLEAGUE.BOWLERS b GROUP BY b.TeamID ORDER BY total_quantity DESC LIMIT 10;
SELECT tma.Lanes AS category_topic, COUNT(*) AS event_cnt FROM BOWLINGLEAGUE.TOURNEY_MATCHES_ARCHIVE tma GROUP BY tma.Lanes ORDER BY event_cnt DESC LIMIT 10;
SELECT COUNT(*) AS row_cnt FROM DIMENSIONS_AI_COVID19.CLINICAL_TRIALS ct;
SELECT COUNT(DISTINCT ct.id) AS distinct_external_cnt FROM DIMENSIONS_AI_COVID19.CLINICAL_TRIALS ct;
SELECT COUNT(DISTINCT ct.linkout) AS distinct_entity_cnt FROM DIMENSIONS_AI_COVID19.CLINICAL_TRIALS ct;
SELECT ct.registry AS rel_entity, COUNT(*) AS event_cnt FROM DIMENSIONS_AI_COVID19.CLINICAL_TRIALS ct GROUP BY ct.registry ORDER BY event_cnt DESC LIMIT 10;
SELECT ct.title AS name_entity, COUNT(*) AS event_cnt FROM DIMENSIONS_AI_COVID19.CLINICAL_TRIALS ct GROUP BY ct.title ORDER BY event_cnt DESC LIMIT 10;
SELECT distinct ct.id AS id_external FROM DIMENSIONS_AI_COVID19.CLINICAL_TRIALS ct WHERE ct.title LIKE '%good%' ORDER BY ct.id LIMIT 10;
SELECT ct.study_type AS rel_entity, SUM(ct.study_participants) AS total_quantity FROM DIMENSIONS_AI_COVID19.CLINICAL_TRIALS ct GROUP BY ct.study_type ORDER BY total_quantity DESC LIMIT 10;
SELECT ct.study_type AS category_topic, COUNT(*) AS event_cnt FROM DIMENSIONS_AI_COVID19.CLINICAL_TRIALS ct GROUP BY ct.study_type ORDER BY event_cnt DESC LIMIT 10;
SELECT ct.title AS name_entity, AVG(ct.study_participants) AS avg_quantity FROM DIMENSIONS_AI_COVID19.CLINICAL_TRIALS ct WHERE ct.study_participants IS NOT NULL GROUP BY ct.title ORDER BY avg_quantity DESC LIMIT 10;
SELECT tr.transaction_hash AS id_external FROM ETHEREUM_BLOCKCHAIN.TRANSACTIONS tx JOIN ETHEREUM_BLOCKCHAIN.TRACES tr ON tr.transaction_hash = tx.hash WHERE tx.input LIKE '%0x%' ORDER BY tx.block_timestamp DESC LIMIT 10;
SELECT tr.transaction_hash AS id_external FROM ETHEREUM_BLOCKCHAIN.TRANSACTIONS tx JOIN ETHEREUM_BLOCKCHAIN.TRACES tr ON tr.transaction_hash = tx.hash WHERE FROM_UNIXTIME(tx.block_timestamp / 1000000) >= '2015-01-01 00:00:00' AND FROM_UNIXTIME(tx.block_timestamp / 1000000) < '2020-01-31 23:59:59' ORDER BY tx.block_timestamp DESC LIMIT 10;
SELECT tr.transaction_hash AS id_external FROM ETHEREUM_BLOCKCHAIN.TRANSACTIONS tx JOIN ETHEREUM_BLOCKCHAIN.TRACES tr ON tr.transaction_hash = tx.hash WHERE tx.receipt_status = 1 ORDER BY tx.block_timestamp DESC LIMIT 10;
SELECT tr.transaction_hash AS id_external FROM ETHEREUM_BLOCKCHAIN.TRANSACTIONS tx JOIN ETHEREUM_BLOCKCHAIN.TRACES tr ON tr.transaction_hash = tx.hash WHERE FROM_UNIXTIME(tx.block_timestamp / 1000000) >= '2015-01-01 00:00:00' AND FROM_UNIXTIME(tx.block_timestamp / 1000000) < '2020-01-31 23:59:59' AND tx.receipt_status = 1 AND tx.input LIKE CONCAT('%', '0x', '%') ORDER BY tx.block_timestamp DESC LIMIT 10;
SELECT COUNT(*) AS event_cnt FROM ETHEREUM_BLOCKCHAIN.TRANSACTIONS tx JOIN ETHEREUM_BLOCKCHAIN.TRACES tr ON tr.transaction_hash = tx.hash WHERE FROM_UNIXTIME(tx.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(tx.block_timestamp / 1000000) < '2026-01-31 23:59:59';
SELECT COUNT(DISTINCT tr.to_address) AS distinct_entity_cnt FROM ETHEREUM_BLOCKCHAIN.TRANSACTIONS tx JOIN ETHEREUM_BLOCKCHAIN.TRACES tr ON tr.transaction_hash = tx.hash WHERE FROM_UNIXTIME(tx.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(tx.block_timestamp / 1000000) < '2026-01-31 23:59:59';
SELECT SUM(tx.value) AS total_amount FROM ETHEREUM_BLOCKCHAIN.TRANSACTIONS tx JOIN ETHEREUM_BLOCKCHAIN.TRACES tr ON tr.transaction_hash = tx.hash WHERE FROM_UNIXTIME(tx.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(tx.block_timestamp / 1000000) < '2026-01-31 23:59:59';
SELECT AVG(tx.value) AS avg_amount, AVG(tx.receipt_gas_used) AS avg_quantity FROM ETHEREUM_BLOCKCHAIN.TRANSACTIONS tx JOIN ETHEREUM_BLOCKCHAIN.TRACES tr ON tr.transaction_hash = tx.hash WHERE FROM_UNIXTIME(tx.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(tx.block_timestamp / 1000000) < '2026-01-31 23:59:59';
SELECT tr.trace_type AS category_topic, COUNT(*) AS event_cnt FROM ETHEREUM_BLOCKCHAIN.TRACES tr WHERE FROM_UNIXTIME(tr.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(tr.block_timestamp / 1000000) < '2026-01-31 23:59:59' GROUP BY tr.trace_type ORDER BY event_cnt DESC LIMIT 10;
SELECT tr.trace_type AS category_topic, COUNT(DISTINCT tr.to_address) AS distinct_entity_cnt FROM ETHEREUM_BLOCKCHAIN.TRACES tr WHERE FROM_UNIXTIME(tr.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(tr.block_timestamp / 1000000) < '2026-01-31 23:59:59' GROUP BY tr.trace_type ORDER BY distinct_entity_cnt DESC LIMIT 10;
SELECT tk.name AS name_entity, COUNT(*) AS event_cnt FROM ETHEREUM_BLOCKCHAIN.TOKEN_TRANSFERS tt JOIN ETHEREUM_BLOCKCHAIN.TOKENS tk ON tt.token_address = tk.address WHERE FROM_UNIXTIME(tt.block_timestamp / 1000000) >= '2015-01-01 00:00:00' AND FROM_UNIXTIME(tt.block_timestamp / 1000000) < '2020-01-31 23:59:59' GROUP BY tk.name ORDER BY event_cnt DESC LIMIT 10;
SELECT tk.name AS name_entity, SUM(CAST(tt.value AS DECIMAL(65, 0))) AS total_amount FROM ETHEREUM_BLOCKCHAIN.TOKEN_TRANSFERS tt JOIN ETHEREUM_BLOCKCHAIN.TOKENS tk ON tt.token_address = tk.address WHERE FROM_UNIXTIME(tt.block_timestamp / 1000000) >= '2015-01-01 00:00:00' AND FROM_UNIXTIME(tt.block_timestamp / 1000000) < '2020-01-31 23:59:59' GROUP BY tk.name ORDER BY total_amount DESC LIMIT 10;
SELECT DATE(FROM_UNIXTIME(tx.block_timestamp / 1000000.0)) AS day, COUNT(*) AS event_cnt FROM ETHEREUM_BLOCKCHAIN.TRANSACTIONS tx JOIN ETHEREUM_BLOCKCHAIN.TRACES tr ON tr.transaction_hash = tx.hash WHERE tx.block_timestamp >= UNIX_TIMESTAMP('2016-01-01 00:00:00') * 1000000.0 AND tx.block_timestamp < UNIX_TIMESTAMP('2020-01-31 23:59:59') * 1000000.0 GROUP BY day ORDER BY day;
SELECT DATE(FROM_UNIXTIME(tr.block_timestamp / 1000000.0)) AS day, tr.trace_type AS category_topic, COUNT(*) AS event_cnt FROM ETHEREUM_BLOCKCHAIN.TRACES tr WHERE FROM_UNIXTIME(tr.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(tr.block_timestamp / 1000000) < '2026-01-31 23:59:59' GROUP BY day, tr.trace_type ORDER BY day, event_cnt DESC;
SELECT tk.name AS name_entity, COUNT(*) AS event_cnt FROM ETHEREUM_BLOCKCHAIN.TOKEN_TRANSFERS tt JOIN ETHEREUM_BLOCKCHAIN.TOKENS tk ON tt.token_address = tk.address WHERE FROM_UNIXTIME(tt.block_timestamp / 1000000) >= '2015-01-01 00:00:00' AND FROM_UNIXTIME(tt.block_timestamp / 1000000) < '2020-01-31 23:59:59' GROUP BY tk.name HAVING COUNT(*) >= 5 ORDER BY event_cnt DESC;
SELECT tk.name AS name_entity, AVG(CAST(tt.value AS DECIMAL)) AS avg_amount FROM ETHEREUM_BLOCKCHAIN.TOKEN_TRANSFERS tt JOIN ETHEREUM_BLOCKCHAIN.TOKENS tk ON tt.token_address = tk.address WHERE FROM_UNIXTIME(tt.block_timestamp / 1000000) >= '2015-01-01 00:00:00' AND FROM_UNIXTIME(tt.block_timestamp / 1000000) < '2020-01-31 23:59:59' AND tt.value IS NOT NULL GROUP BY tk.name ORDER BY avg_amount DESC LIMIT 10;
WITH topic_cnt AS ( SELECT tr.trace_type AS topic, COUNT(*) AS cnt FROM ETHEREUM_BLOCKCHAIN.TRACES tr WHERE FROM_UNIXTIME(tr.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(tr.block_timestamp / 1000000) < '2026-01-31 23:59:59' GROUP BY tr.trace_type ), avg_cnt AS ( SELECT AVG(cnt) AS avg_cnt FROM topic_cnt ) SELECT topic, cnt FROM topic_cnt WHERE cnt > (SELECT avg_cnt FROM avg_cnt) ORDER BY cnt DESC LIMIT 10;
SELECT tr.trace_type AS category_topic, SUM(tx.value) AS total_amount FROM ETHEREUM_BLOCKCHAIN.TRANSACTIONS tx JOIN ETHEREUM_BLOCKCHAIN.TRACES tr ON tr.transaction_hash = tx.hash WHERE FROM_UNIXTIME(tx.block_timestamp / 1000000) >= '2015-01-01 00:00:00' AND FROM_UNIXTIME(tx.block_timestamp / 1000000) < '2020-01-31 23:59:59' GROUP BY tr.trace_type ORDER BY total_amount DESC LIMIT 10;
SELECT tr.trace_type AS category_topic, SUM(tx.value) AS total_amount FROM ETHEREUM_BLOCKCHAIN.TRANSACTIONS tx JOIN ETHEREUM_BLOCKCHAIN.TRACES tr ON tr.transaction_hash = tx.hash WHERE FROM_UNIXTIME(tx.block_timestamp / 1000000) >= '1970-01-01 00:00:00' AND FROM_UNIXTIME(tx.block_timestamp / 1000000) < '1978-01-31 23:59:59' GROUP BY tr.trace_type HAVING SUM(tx.value) >= 1000 ORDER BY total_amount DESC;
SELECT tr.trace_type AS category_topic, SUM( tx.receipt_status ) / COUNT(*) AS ratio_in_status FROM ETHEREUM_BLOCKCHAIN.TRANSACTIONS tx JOIN ETHEREUM_BLOCKCHAIN.TRACES tr ON tr.transaction_hash = tx.hash WHERE FROM_UNIXTIME(tx.block_timestamp/ 1000000) >= '2015-01-01 00:00:00' AND FROM_UNIXTIME(tx.block_timestamp/ 1000000) < '2020-01-31 23:59:59' GROUP BY tr.trace_type ORDER BY ratio_in_status DESC;
SELECT SUM(tx.receipt_gas_used) AS total_quantity FROM ETHEREUM_BLOCKCHAIN.TRANSACTIONS tx JOIN ETHEREUM_BLOCKCHAIN.TRACES tr ON tr.transaction_hash = tx.hash WHERE FROM_UNIXTIME(tx.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(tx.block_timestamp / 1000000) < '2026-01-31 23:59:59';
SELECT tr.trace_type AS category_topic, SUM(tx.receipt_gas_used) AS total_quantity FROM ETHEREUM_BLOCKCHAIN.TRANSACTIONS tx JOIN ETHEREUM_BLOCKCHAIN.TRACES tr ON tr.transaction_hash = tx.hash WHERE FROM_UNIXTIME(tx.block_timestamp / 1000000) >= '2015-01-01 00:00:00' AND FROM_UNIXTIME(tx.block_timestamp / 1000000) < '2020-01-31 23:59:59' GROUP BY tr.trace_type ORDER BY total_quantity DESC LIMIT 10;
SELECT hl.osm_id AS id_external FROM GEO_OPENSTREETMAP_WORLDPOP.GEO_OPENSTREETMAP_HISTORY_LAYERS hl WHERE FROM_UNIXTIME(hl.osm_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(hl.osm_timestamp / 1000000) < '2026-01-31 23:59:59' ORDER BY hl.osm_timestamp DESC LIMIT 10;
SELECT COUNT(*) AS event_cnt FROM GEO_OPENSTREETMAP_WORLDPOP.GEO_OPENSTREETMAP_HISTORY_LAYERS hl WHERE FROM_UNIXTIME(hl.osm_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(hl.osm_timestamp / 1000000) < '2026-01-31 23:59:59';
SELECT COUNT(DISTINCT hn.changeset) AS distinct_entity_cnt FROM GEO_OPENSTREETMAP_WORLDPOP.GEO_OPENSTREETMAP_HISTORY_NODES hn WHERE FROM_UNIXTIME(hn.osm_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(hn.osm_timestamp / 1000000) < '2026-01-31 23:59:59';
SELECT hl.layer_class AS category_topic, COUNT(*) AS event_cnt FROM GEO_OPENSTREETMAP_WORLDPOP.GEO_OPENSTREETMAP_HISTORY_LAYERS hl WHERE FROM_UNIXTIME(hl.osm_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(hl.osm_timestamp / 1000000) < '2026-01-31 23:59:59' GROUP BY hl.layer_class ORDER BY event_cnt DESC LIMIT 10;
SELECT hl.layer_name AS name_entity, COUNT(*) AS event_cnt FROM GEO_OPENSTREETMAP_WORLDPOP.GEO_OPENSTREETMAP_HISTORY_LAYERS hl WHERE FROM_UNIXTIME(hl.osm_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(hl.osm_timestamp / 1000000) < '2026-01-31 23:59:59' GROUP BY hl.layer_name ORDER BY event_cnt DESC LIMIT 10;
SELECT pf.geometry AS location, COUNT(*) AS event_cnt FROM GEO_OPENSTREETMAP_WORLDPOP.GEO_OPENSTREETMAP_PLANET_LAYERS pl JOIN GEO_OPENSTREETMAP_WORLDPOP.GEO_OPENSTREETMAP_PLANET_FEATURES pf ON pl.osm_way_id = pf.osm_way_id WHERE FROM_UNIXTIME(pl.osm_timestamp / 1000000) >= '2021-01-01 00:00:00' AND FROM_UNIXTIME(pl.osm_timestamp / 1000000) < '2026-01-31 23:59:59' GROUP BY pf.geometry ORDER BY event_cnt DESC LIMIT 10;
SELECT DATE(FROM_UNIXTIME(hl.osm_timestamp / 1000000.0)) AS day, COUNT(*) AS event_cnt FROM GEO_OPENSTREETMAP_WORLDPOP.GEO_OPENSTREETMAP_HISTORY_LAYERS hl WHERE FROM_UNIXTIME(hl.osm_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(hl.osm_timestamp / 1000000) < '2026-01-31 23:59:59' GROUP BY day ORDER BY day;
SELECT DATE(FROM_UNIXTIME(hl.osm_timestamp / 1000000.0)) AS day, hl.layer_class AS category_topic, COUNT(*) AS event_cnt FROM GEO_OPENSTREETMAP_WORLDPOP.GEO_OPENSTREETMAP_HISTORY_LAYERS hl WHERE FROM_UNIXTIME(hl.osm_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(hl.osm_timestamp / 1000000) < '2026-01-31 23:59:59' GROUP BY day, hl.layer_class ORDER BY day, event_cnt DESC;
SELECT hl.layer_name AS name_entity, COUNT(*) AS event_cnt FROM GEO_OPENSTREETMAP_WORLDPOP.GEO_OPENSTREETMAP_HISTORY_LAYERS hl WHERE FROM_UNIXTIME(hl.osm_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(hl.osm_timestamp / 1000000) < '2026-01-31 23:59:59' GROUP BY hl.layer_name HAVING COUNT(*) >= 10 ORDER BY event_cnt DESC;
WITH topic_cnt AS ( SELECT hl.layer_class AS topic, COUNT(*) AS cnt FROM GEO_OPENSTREETMAP_WORLDPOP.GEO_OPENSTREETMAP_HISTORY_LAYERS hl WHERE FROM_UNIXTIME(hl.osm_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(hl.osm_timestamp / 1000000) < '2026-01-31 23:59:59' GROUP BY hl.layer_class ), avg_cnt AS ( SELECT AVG(cnt) AS avg_cnt FROM topic_cnt ) SELECT topic, cnt FROM topic_cnt WHERE cnt > (SELECT avg_cnt FROM avg_cnt) ORDER BY cnt DESC LIMIT 10;
SELECT ar.issue_invoice_apply_code AS id_external FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59' ORDER BY ar.make_account_date DESC LIMIT 10;
SELECT COUNT(*) AS event_cnt FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59';
SELECT COUNT(DISTINCT ar.project_id) AS distinct_entity_cnt FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59';
SELECT SUM(ar.income_amount_domestic) AS total_amount FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59';
SELECT AVG(ar.income_amount_domestic) AS avg_amount, AVG(ar.overdue_days) AS avg_quantity FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59';
SELECT ar.customer_type AS category_topic, COUNT(*) AS event_cnt FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59' GROUP BY ar.customer_type ORDER BY event_cnt DESC LIMIT 10;
SELECT ar.customer_type AS category_topic, COUNT(DISTINCT ar.company_id) AS distinct_entity_cnt FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59' GROUP BY ar.customer_type ORDER BY distinct_entity_cnt DESC LIMIT 10;
SELECT ar.company_name AS name_entity, COUNT(*) AS event_cnt FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59' GROUP BY ar.company_name ORDER BY event_cnt DESC LIMIT 10;
SELECT ar.company_name AS name_entity, SUM(ar.income_amount_domestic) AS total_amount FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59' GROUP BY ar.company_name ORDER BY total_amount DESC LIMIT 10;
SELECT ar.project_mgr_id AS rel_person, COUNT(*) AS event_cnt FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59' GROUP BY ar.project_mgr_id ORDER BY event_cnt DESC LIMIT 10;
SELECT DATE( ar.make_account_date) AS day, COUNT(*) AS event_cnt FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59' GROUP BY day ORDER BY day;
SELECT DATE_FORMAT(ar.make_account_date, '%Y-%m-01') AS month, SUM(ar.income_amount_domestic) AS total_amount FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59' GROUP BY month ORDER BY month;
SELECT DATE( ar.make_account_date) AS day, ar.customer_type AS category_topic, COUNT(*) AS event_cnt FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59' GROUP BY day, ar.customer_type ORDER BY day, event_cnt DESC;
SELECT ar.company_name AS name_entity, COUNT(*) AS event_cnt FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59' GROUP BY ar.company_name HAVING COUNT(*) >= 10 ORDER BY event_cnt DESC;
SELECT ar.company_name AS name_entity, AVG(ar.income_amount_domestic) AS avg_amount FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59' AND ar.income_amount_domestic IS NOT NULL GROUP BY ar.company_name ORDER BY avg_amount DESC LIMIT 10;
WITH topic_cnt AS ( SELECT ar.customer_type AS topic, COUNT(*) AS cnt FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59' GROUP BY ar.customer_type ), avg_cnt AS ( SELECT AVG(cnt) AS avg_cnt FROM topic_cnt ) SELECT topic, cnt FROM topic_cnt WHERE cnt > (SELECT avg_cnt FROM avg_cnt) ORDER BY cnt DESC LIMIT 10;
SELECT ar.project_mgr_id AS rel_person, ar.customer_type AS category_topic, COUNT(*) AS event_cnt FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59' GROUP BY ar.project_mgr_id, ar.customer_type ORDER BY event_cnt DESC LIMIT 10;
SELECT ar.customer_type AS category_topic, SUM(ar.income_amount_domestic) AS total_amount FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59' GROUP BY ar.customer_type ORDER BY total_amount DESC LIMIT 10;
SELECT ar.customer_type AS category_topic, SUM(ar.income_amount_domestic) AS total_amount FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59' GROUP BY ar.customer_type HAVING SUM(ar.income_amount_domestic) >= 1000 ORDER BY total_amount DESC;
WITH agg AS ( SELECT ar.customer_type AS topic, ar.company_name AS entity, SUM(ar.income_amount_domestic) AS total_amount FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59' GROUP BY ar.customer_type, ar.company_name ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY total_amount DESC) AS rn FROM agg ) SELECT topic, entity, total_amount FROM ranked WHERE rn = 1 ORDER BY total_amount DESC LIMIT 10;
SELECT SUM(ar.overdue_days) AS total_quantity FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59';
SELECT ar.customer_type AS category_topic, SUM(ar.overdue_days) AS total_quantity FROM ods_crm.crm_account_receivable ar WHERE ar.make_account_date >= '2001-01-01 00:00:00' AND ar.make_account_date < '2026-01-31 23:59:59' GROUP BY ar.customer_type ORDER BY total_quantity DESC LIMIT 10;
SELECT COUNT(*) AS row_cnt FROM PYPI.DISTRIBUTION_METADATA dm;
SELECT COUNT(DISTINCT dm.sha256_digest) AS distinct_external_cnt FROM PYPI.DISTRIBUTION_METADATA dm;
SELECT COUNT(DISTINCT dm.requires_dist) AS distinct_entity_cnt FROM PYPI.DISTRIBUTION_METADATA dm;
SELECT dm.requires_dist AS rel_entity, COUNT(*) AS event_cnt FROM PYPI.DISTRIBUTION_METADATA dm GROUP BY dm.requires_dist ORDER BY event_cnt DESC LIMIT 10;
SELECT dm.name AS name_entity, COUNT(*) AS event_cnt FROM PYPI.DISTRIBUTION_METADATA dm GROUP BY dm.name ORDER BY event_cnt DESC LIMIT 10;
SELECT distinct dm.sha256_digest AS id_external FROM PYPI.DISTRIBUTION_METADATA dm WHERE dm.name LIKE '%safa%' ORDER BY dm.sha256_digest LIMIT 10;
SELECT dm.path AS location, COUNT(DISTINCT dm.sha256_digest) AS distinct_external_cnt FROM PYPI.DISTRIBUTION_METADATA dm GROUP BY dm.path ORDER BY distinct_external_cnt DESC LIMIT 10;
